import {
  createServer as createHttpServer,
  type IncomingMessage,
  type Server,
  type ServerResponse,
} from 'node:http';
import type { ErrorResponse, HealthResponse } from './shared/contract-types.ts';

/** 默认监听端口，可用 PORT 环境变量覆盖。 */
export const DEFAULT_PORT = 8792;

/** 监听地址固定为回环地址 127.0.0.1。 */
export const DEFAULT_HOST = '127.0.0.1';

/** 解析 PORT 环境变量；缺省或非法值回退到 DEFAULT_PORT。 */
export function resolvePort(raw: string | undefined): number {
  if (raw === undefined) {
    return DEFAULT_PORT;
  }
  const trimmed = raw.trim();
  if (trimmed === '') {
    return DEFAULT_PORT;
  }
  const parsed = Number(trimmed);
  if (!Number.isInteger(parsed) || parsed < 0 || parsed > 65535) {
    return DEFAULT_PORT;
  }
  return parsed;
}

/** 以 application/json 写出响应体。 */
export function sendJson(res: ServerResponse, statusCode: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.statusCode = statusCode;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Content-Length', String(Buffer.byteLength(payload, 'utf8')));
  res.end(payload);
}

/** 按契约 ErrorResponse 结构写出 JSON 错误响应。 */
export function sendError(res: ServerResponse, statusCode: number, message: string): void {
  const body: ErrorResponse = { error: message };
  sendJson(res, statusCode, body);
}

/** 路由处理入口：当前实现 GET /health，其余路径统一返回 JSON 404。 */
export function handleRequest(req: IncomingMessage, res: ServerResponse): void {
  const method = (req.method ?? 'GET').toUpperCase();

  let pathname = '/';
  try {
    const url = new URL(req.url ?? '/', `http://${req.headers.host ?? DEFAULT_HOST}`);
    pathname = url.pathname;
  } catch {
    sendError(res, 400, '无法解析的请求地址');
    return;
  }

  if (pathname === '/health' && method === 'GET') {
    const body: HealthResponse = { status: 'ok' };
    sendJson(res, 200, body);
    return;
  }

  sendError(res, 404, `未找到资源：${method} ${pathname}`);
}

/** 创建一个尚未开始监听的 HTTP 服务实例，供测试直接复用。 */
export function createServer(): Server {
  return createHttpServer(handleRequest);
}

/** createServer 的别名，便于以「应用工厂」命名调用。 */
export const createApp = createServer;

/** 创建服务并立即在 host:port 上监听。 */
export function startServer(port: number = DEFAULT_PORT, host: string = DEFAULT_HOST): Server {
  const server = createServer();
  server.listen(port, host);
  return server;
}
