{"files":[{"path":"src/http.ts","content":"import { Buffer } from 'node:buffer';
import type { IncomingMessage, ServerResponse } from 'node:http';
import type { ErrorResponse } from './shared/contract-types.ts';

/** 允许缓冲的请求体上限（字节），避免无限制读取。 */
export const MAX_BODY_BYTES = 1024 * 1024;

/** 以 application/json 写出响应体（含 Content-Length）。 */
export function sendJson(res: ServerResponse, statusCode: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.statusCode = statusCode;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Content-Length', String(Buffer.byteLength(payload, 'utf8')));
  res.end(payload);
}

/** 按契约 ErrorResponse 结构写出 JSON 错误响应。 */
export function sendError(res: ServerResponse, statusCode: number, message: string): void {
  const body: ErrorResponse = { error: message };
  sendJson(res, statusCode, body);
}

/** 请求体解析结果：成功时携带解析后的任意值，失败时携带可读原因。 */
export type JsonBodyResult =
  | { ok: true; value: unknown }
  | { ok: false; message: string };

/**
 * 读取并解析请求体为 JSON。
 * 空体、非法 JSON、超出长度上限、读取错误都返回 ok:false，由调用方决定状态码。
 */
export function readJsonBody(req: IncomingMessage): Promise<JsonBodyResult> {
  return new Promise<JsonBodyResult>((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let settled = false;

    const settle = (result: JsonBodyResult): void => {
      if (settled) {
        return;
      }
      settled = true;
      resolve(result);
    };

    req.on('data', (chunk: Buffer) => {
      if (settled) {
        return;
      }
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        settle({ ok: false, message: '请求体过大' });
        return;
      }
      chunks.push(chunk);
    });

    req.on('end', () => {
      if (settled) {
        return;
      }
      const raw = Buffer.concat(chunks).toString('utf8').trim();
      if (raw === '') {
        settle({ ok: false, message: '请求体不能为空' });
        return;
      }
      try {
        const parsed: unknown = JSON.parse(raw);
        settle({ ok: true, value: parsed });
      } catch {
        settle({ ok: false, message: '请求体不是合法的 JSON' });
      }
    });

    req.on('error', () => {
      settle({ ok: false, message: '读取请求体失败' });
    });
  });
}
"},{"path":"src/tasks/store.ts","content":"import { randomUUID } from 'node:crypto';
import type { Task, TaskStatus } from '../shared/contract-types.ts';

/** 任务状态的唯一事实来源：POST 校验、GET 过滤、PATCH 校验全部复用它。 */
export const TASK_STATUSES: readonly TaskStatus[] = ['todo', 'doing', 'done'];

/** 进程内内存仓库（模块级单例），不写入任何持久化介质。 */
const tasks = new Map<string, Task>();

/** 判断任意值是否为合法的任务状态。 */
export function isTaskStatus(value: unknown): value is TaskStatus {
  return typeof value === 'string' && (TASK_STATUSES as readonly string[]).includes(value);
}

/** 创建任务所需的输入。 */
export interface CreateTaskInput {
  title: string;
  status?: TaskStatus;
}

/**
 * 列出任务：status 为 undefined 时返回全部；否则按 status 精确匹配。
 * 非法 status 值自然匹配不到任何任务，返回空数组。
 */
export function listTasks(status?: string): Task[] {
  const all = Array.from(tasks.values());
  if (status === undefined) {
    return all;
  }
  return all.filter((task) => task.status === status);
}

/** 创建任务：id 唯一非空，createdAt 为 ISO 8601，status 缺省为 'todo'。 */
export function createTask(input: CreateTaskInput): Task {
  const task: Task = {
    id: randomUUID(),
    title: input.title,
    status: input.status ?? 'todo',
    createdAt: new Date().toISOString(),
  };
  tasks.set(task.id, task);
  return task;
}

/** 按 id 查询单个任务，不存在返回 undefined。 */
export function getTask(id: string): Task | undefined {
  return tasks.get(id);
}

/** 更新任务状态并返回更新后的对象，id 不存在返回 undefined。 */
export function updateTaskStatus(id: string, status: TaskStatus): Task | undefined {
  const existing = tasks.get(id);
  if (existing === undefined) {
    return undefined;
  }
  const updated: Task = { ...existing, status };
  tasks.set(id, updated);
  return updated;
}

/** 删除任务并返回被删除的对象，id 不存在返回 undefined。 */
export function deleteTask(id: string): Task | undefined {
  const existing = tasks.get(id);
  if (existing === undefined) {
    return undefined;
  }
  tasks.delete(id);
  return existing;
}

/** 清空内存仓库（仅测试使用）。 */
export function resetStore(): void {
  tasks.clear();
}
"},{"path":"src/tasks/routes.ts","content":"import type { IncomingMessage, ServerResponse } from 'node:http';
import type { CreateTaskRequest, Task } from '../shared/contract-types.ts';
import { readJsonBody, sendError, sendJson } from '../http.ts';
import { createTask, isTaskStatus, listTasks } from './store.ts';

/** 任务集合资源的路径。 */
export const TASKS_PATH = '/api/tasks';

/** 仅接受非数组的普通对象作为请求体。 */
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** GET /api/tasks[?status=]：返回全部任务，或按 status 精确过滤后的任务。 */
function handleListTasks(res: ServerResponse, url: URL): void {
  const status = url.searchParams.get('status');
  const result: Task[] = listTasks(status === null ? undefined : status);
  sendJson(res, 200, result);
}

/** POST /api/tasks：title 缺失/空白 → 400；合法请求返回 201 与新建任务。 */
async function handleCreateTask(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const parsed = await readJsonBody(req);
  if (!parsed.ok) {
    sendError(res, 400, parsed.message);
    return;
  }
  if (!isPlainObject(parsed.value)) {
    sendError(res, 400, '请求体必须是 JSON 对象');
    return;
  }

  const rawTitle = parsed.value['title'];
  if (typeof rawTitle !== 'string' || rawTitle.trim() === '') {
    sendError(res, 400, 'title 必填且不能为空字符串');
    return;
  }
  const title = rawTitle.trim();

  const rawStatus = parsed.value['status'];
  let payload: CreateTaskRequest;
  if (rawStatus === undefined) {
    payload = { title };
  } else if (isTaskStatus(rawStatus)) {
    payload = { title, status: rawStatus };
  } else {
    sendError(res, 400, "status 必须是 'todo' | 'doing' | 'done' 之一");
    return;
  }

  const created: Task = createTask(payload);
  sendJson(res, 201, created);
}

/**
 * 处理 /api/tasks 集合资源。
 * 返回 true 表示已接管该请求（已写出响应）；false 表示方法不被支持，由调用方决定后续分支。
 */
export function handleTasksCollection(
  req: IncomingMessage,
  res: ServerResponse,
  url: URL,
  method: string,
): boolean {
  if (method === 'GET') {
    handleListTasks(res, url);
    return true;
  }
  if (method === 'POST') {
    void handleCreateTask(req, res).catch(() => {
      if (!res.writableEnded) {
        sendError(res, 500, '服务内部错误');
      }
    });
    return true;
  }
  return false;
}
